88	// enableUsesSetupFlow reports whether `entire enable` should delegate to the
89	// setup/configure flow instead of the lightweight re-enable path.
90	// Bare `enable` and `enable --local/--project` remain state-toggle operations;
91	// any other setup-mutating flag should share configure's behavior.
92	func enableUsesSetupFlow(cmd *cobra.Command, agentName string) bool {
93		if agentName != "" || hasStrategyFlags(cmd) {
94			return true
95		}
96	
97		return cmd.Flags().Changed("force") ||
98			cmd.Flags().Changed("local-dev") ||
99			cmd.Flags().Changed("absolute-git-hook-path") ||
100			cmd.Flags().Changed("telemetry")
101	}
