110	// updateStrategyOptions applies strategy flags to settings without re-running agent setup.
111	// Loads and writes only the target file to avoid leaking settings between layers.
112	func updateStrategyOptions(ctx context.Context, w io.Writer, opts EnableOptions) error {
113		// Validate before doing any I/O so we don't report "Settings updated" on bad input.
114		if opts.CheckpointRemote != "" {
115			if _, _, err := parseCheckpointRemoteFlag(opts.CheckpointRemote); err != nil {
116				return fmt.Errorf("invalid --checkpoint-remote: %w", err)
117			}
118		}
119	
120		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
121	
122		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
123		if err != nil {
124			targetFileAbs = targetFile
125		}
126	
127		s, err := settings.LoadFromFile(targetFileAbs)
128		if err != nil {
129			return fmt.Errorf("failed to load settings: %w", err)
130		}
131	
132		opts.applyStrategyOptions(s)
133	
134		if targetFile == settings.EntireSettingsLocalFile {
135			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
136				return fmt.Errorf("failed to save settings: %w", err)
137			}
138		} else {
139			if err := SaveEntireSettings(ctx, s); err != nil {
140				return fmt.Errorf("failed to save settings: %w", err)
141			}
142		}
143	
144		fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
145		return nil
146	}
