148	func updateSummaryGenerationSettings(ctx context.Context, w io.Writer, provider, model string, opts EnableOptions) error {
149		if provider == "" && model == "" {
150			return errors.New("at least one of --summarize-provider or --summarize-model must be set")
151		}
152	
153		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
154		targetFileAbs, err := paths.AbsPath(ctx, targetFile)
155		if err != nil {
156			targetFileAbs = targetFile
157		}
158	
159		s, err := settings.LoadFromFile(targetFileAbs)
160		if err != nil {
161			return fmt.Errorf("failed to load settings: %w", err)
162		}
163		if s.SummaryGeneration == nil {
164			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
165		}
166	
167		if provider != "" {
168			if err := validateSummaryProvider(provider); err != nil {
169				return err
170			}
171		}
172		if model != "" && provider == "" && s.SummaryGeneration.Provider == "" {
173			// The target file alone has no provider, but the merged runtime
174			// settings might (e.g. provider in project, model override in local).
175			// Check the full merged view before rejecting.
176			merged, mergeErr := settings.Load(ctx)
177			if mergeErr != nil || merged.SummaryGeneration == nil || merged.SummaryGeneration.Provider == "" {
178				return errors.New("--summarize-model requires an existing summary provider or --summarize-provider")
179			}
180		}
181	
182		s.SummaryGeneration.SetProvider(provider, model)
183	
184		if targetFile == settings.EntireSettingsLocalFile {
185			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
186				return fmt.Errorf("failed to save settings: %w", err)
187			}
188		} else {
189			if err := SaveEntireSettings(ctx, s); err != nil {
190				return fmt.Errorf("failed to save settings: %w", err)
191			}
192		}
193	
194		fmt.Fprintf(w, "✓ Settings updated (%s)\n", configDisplay)
195		return nil
196	}
