265	// runSetupFlow runs the first-time setup flow (agent selection + hooks + settings).
266	// Shared by root command (no args), `entire configure`, and `entire enable` on fresh repos.
267	func runSetupFlow(ctx context.Context, w io.Writer, opts EnableOptions) error {
268		// Discover external agent plugins so they appear in agent selection.
269		// Use DiscoverAndRegisterAlways to bypass the external_agents setting —
270		// during setup the setting doesn't exist yet.
271		external.DiscoverAndRegisterAlways(ctx)
272	
273		agents, err := detectOrSelectAgent(ctx, w, nil)
274		if err != nil {
275			return fmt.Errorf("agent selection failed: %w", err)
276		}
277	
278		return runEnableInteractive(ctx, w, agents, opts)
279	}
