787	// runEnableInteractive runs the interactive enable flow.
788	// agents must be provided by the caller (via detectOrSelectAgent).
789	func runEnableInteractive(ctx context.Context, w io.Writer, agents []agent.Agent, opts EnableOptions) error {
790		// Uninstall hooks for agents that were previously active but are no longer selected
791		if err := uninstallDeselectedAgentHooks(ctx, w, agents); err != nil {
792			return fmt.Errorf("failed to clean up deselected agents: %w", err)
793		}
794	
795		// Setup agent hooks for all selected agents
796		for _, ag := range agents {
797			if _, err := setupAgentHooks(ctx, w, ag, opts.LocalDev, opts.ForceHooks); err != nil {
798				return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
799			}
800		}
801	
802		// Setup .entire directory
803		if _, err := setupEntireDirectory(ctx); err != nil {
804			return fmt.Errorf("failed to setup .entire directory: %w", err)
805		}
806	
807		// Load existing settings to preserve other options (like strategy_options.push)
808		settings, err := LoadEntireSettings(ctx)
809		if err != nil {
810			// If we can't load, start with defaults
811			settings = &EntireSettings{}
812		}
813		// Update the specific fields
814		settings.Enabled = true
815		if opts.LocalDev {
816			settings.LocalDev = true
817		}
818		if opts.AbsoluteGitHookPath {
819			settings.AbsoluteGitHookPath = true
820		}
821	
822		// Auto-enable external_agents if any selected agent is external.
823		for _, ag := range agents {
824			if external.IsExternal(ag) {
825				settings.ExternalAgents = true
826				break
827			}
828		}
829	
830		opts.applyStrategyOptions(settings)
831	
832		// Determine which settings file to write to
833		// First run always creates settings.json (no prompt)
834		entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
835		if err != nil {
836			entireDirAbs = paths.EntireDir // Fallback to relative
837		}
838		shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
839	
840		if showNotification {
841			fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
842			fmt.Fprintln(w, "  Use --project to update the project settings file.")
843		}
844	
845		// Save settings to the appropriate file.
846		targetFile := EntireSettingsFile
847		if shouldUseLocal {
848			targetFile = EntireSettingsLocalFile
849		}
850		saveSettings := func() error {
851			return saveSettingsToTarget(ctx, settings, targetFile)
852		}
853		if err := saveSettings(); err != nil {
854			return fmt.Errorf("failed to save settings: %w", err)
855		}
856	
857		// Use settings values (merged from existing config + flags) for hook installation
858		// This ensures re-running `entire enable` without flags preserves existing settings
859		if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
860			return fmt.Errorf("failed to install git hooks: %w", err)
861		}
862		strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
863		fmt.Fprintln(w, "✓ Hooks installed")
864	
865		configDisplay := configDisplayProject
866		if shouldUseLocal {
867			configDisplay = configDisplayLocal
868		}
869		fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
870	
871		if _, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil); err != nil {
872			return err
873		}
874	
875		// Ask about telemetry consent (only if not already asked)
876		if err := promptTelemetryConsent(settings, opts.Telemetry); err != nil {
877			return fmt.Errorf("telemetry consent: %w", err)
878		}
879		// Save again to persist telemetry choice
880		if err := saveSettings(); err != nil {
881			return fmt.Errorf("failed to save settings: %w", err)
882		}
883	
884		if err := strategy.EnsureSetup(ctx); err != nil {
885			return fmt.Errorf("failed to setup strategy: %w", err)
886		}
887	
888		fmt.Fprintln(w, "\nReady.")
889	
890		// Note about empty repos at the end, after setup is complete
891		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
892			fmt.Fprintln(w)
893			fmt.Fprintln(w, "Note: Session checkpoints require at least one commit. To get started,")
894			fmt.Fprintln(w, "commit the configuration files (e.g. .entire/, .claude/).")
895		}
896	
897		return nil
898	}
