1079	// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
1080	// Returns the detected/selected agents and any error.
1081	//
1082	// On first run (no hooks installed):
1083	//   - Single detected built-in agent: used automatically
1084	//   - Single detected external agent: interactive multi-select prompt
1085	//   - Multiple/no detected agents: interactive multi-select prompt
1086	//
1087	// On re-run (hooks already installed):
1088	//   - Always shows the interactive multi-select
1089	//   - Pre-selects only agents that have hooks installed (respects prior deselection)
1090	//
1091	// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
1092	// It receives available agent names and returns the selected names.
1093	func detectOrSelectAgent(ctx context.Context, w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
1094		// Check for agents with hooks already installed (re-run detection)
1095		installedAgentNames := GetAgentsWithHooksInstalled(ctx)
1096		hasInstalledHooks := len(installedAgentNames) > 0
1097	
1098		// Try auto-detection
1099		detected := agent.DetectAll(ctx)
1100	
1101		// First run: use existing auto-detect shortcuts
1102		if !hasInstalledHooks {
1103			switch {
1104			case len(detected) == 1:
1105				if isBuiltInAgent(detected[0]) {
1106					fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
1107					return detected, nil
1108				}
1109	
1110			case len(detected) > 1:
1111				agentTypes := make([]string, 0, len(detected))
1112				for _, ag := range detected {
1113					agentTypes = append(agentTypes, string(ag.Type()))
1114				}
1115				fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
1116				fmt.Fprintln(w)
1117			}
1118		}
1119	
1120		// Check if we can prompt interactively
1121		if !interactive.CanPromptInteractively() {
1122			if hasInstalledHooks {
1123				// Re-run without TTY — keep currently installed agents
1124				agents := make([]agent.Agent, 0, len(installedAgentNames))
1125				for _, name := range installedAgentNames {
1126					ag, err := agent.Get(name)
1127					if err != nil {
1128						continue
1129					}
1130					agents = append(agents, ag)
1131				}
1132				return agents, nil
1133			}
1134			if len(detected) > 0 {
1135				return detected, nil
1136			}
1137			defaultAgent := agent.Default()
1138			if defaultAgent == nil {
1139				return nil, errors.New("no default agent available")
1140			}
1141			fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
1142			return []agent.Agent{defaultAgent}, nil
1143		}
1144	
1145		// Build pre-selection set.
1146		// On re-run: only pre-select agents with hooks installed (respect prior deselection).
1147		// On first run: pre-select detected built-in agents only.
1148		preSelectedSet := make(map[types.AgentName]struct{})
1149		if hasInstalledHooks {
1150			for _, name := range installedAgentNames {
1151				preSelectedSet[name] = struct{}{}
1152			}
1153		} else {
1154			for _, ag := range detected {
1155				if isBuiltInAgent(ag) {
1156					preSelectedSet[ag.Name()] = struct{}{}
1157				}
1158			}
1159		}
1160	
1161		// Build options from registered agents
1162		agentNames := agent.List()
1163		options := make([]huh.Option[string], 0, len(agentNames))
1164		for _, name := range agentNames {
1165			ag, err := agent.Get(name)
1166			if err != nil {
1167				continue
1168			}
1169			// Only show agents that support hooks
1170			if _, ok := agent.AsHookSupport(ag); !ok {
1171				continue
1172			}
1173			// Skip test-only agents (e.g., Vogon canary)
1174			if to, ok := ag.(agent.TestOnly); ok && to.IsTestOnly() {
1175				continue
1176			}
1177			opt := huh.NewOption(string(ag.Type()), string(name))
1178			if _, isPreSelected := preSelectedSet[name]; isPreSelected {
1179				opt = opt.Selected(true)
1180			}
1181			options = append(options, opt)
1182		}
1183	
1184		if len(options) == 0 {
1185			return nil, errors.New("no agents with hook support available")
1186		}
1187	
1188		// Collect available agent names for the selector
1189		availableNames := make([]string, 0, len(options))
1190		for _, opt := range options {
1191			availableNames = append(availableNames, opt.Value)
1192		}
1193	
1194		var selectedAgentNames []string
1195		if selectFn != nil {
1196			var err error
1197			selectedAgentNames, err = selectFn(availableNames)
1198			if err != nil {
1199				return nil, err
1200			}
1201			if len(selectedAgentNames) == 0 {
1202				return nil, errors.New("no agents selected")
1203			}
1204		} else {
1205			form := NewAccessibleForm(
1206				huh.NewGroup(
1207					huh.NewMultiSelect[string]().
1208						Title("Select the agents you want to use").
1209						Description("Use space to select, enter to confirm.").
1210						Options(options...).
1211						Validate(func(selected []string) error {
1212							if len(selected) == 0 {
1213								return errors.New("please select at least one agent")
1214							}
1215							return nil
1216						}).
1217						Value(&selectedAgentNames),
1218				),
1219			)
1220			if err := form.Run(); err != nil {
1221				return nil, fmt.Errorf("agent selection cancelled: %w", err)
1222			}
1223		}
1224	
1225		selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
1226		for _, name := range selectedAgentNames {
1227			selectedAgent, err := agent.Get(types.AgentName(name))
1228			if err != nil {
1229				return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
1230			}
1231			selectedAgents = append(selectedAgents, selectedAgent)
1232		}
1233	
1234		agentTypes := make([]string, 0, len(selectedAgents))
1235		for _, ag := range selectedAgents {
1236			agentTypes = append(agentTypes, string(ag.Type()))
1237		}
1238		fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
1239		return selectedAgents, nil
1240	}
