1272	// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
1273	// If strategyName is provided, it sets the strategy; otherwise uses default.
1274	func setupAgentHooksNonInteractive(ctx context.Context, w io.Writer, ag agent.Agent, opts EnableOptions) error {
1275		agentName := ag.Name()
1276		// Check if agent supports hooks
1277		if _, ok := agent.AsHookSupport(ag); !ok {
1278			return fmt.Errorf("agent %s does not support hooks", agentName)
1279		}
1280	
1281		fmt.Fprintf(w, "Agent: %s\n\n", ag.Type())
1282	
1283		// Install agent hooks (agent hooks don't depend on settings)
1284		installedHooks, err := setupAgentHooks(ctx, w, ag, opts.LocalDev, opts.ForceHooks)
1285		if err != nil {
1286			return fmt.Errorf("failed to setup %s hooks: %w", agentName, err)
1287		}
1288	
1289		// Setup .entire directory
1290		if _, err := setupEntireDirectory(ctx); err != nil {
1291			return fmt.Errorf("failed to setup .entire directory: %w", err)
1292		}
1293	
1294		// Load existing settings to preserve other options (like strategy_options.push)
1295		settings, err := LoadEntireSettings(ctx)
1296		if err != nil {
1297			// If we can't load, start with defaults
1298			settings = &EntireSettings{}
1299		}
1300		settings.Enabled = true
1301		if opts.LocalDev {
1302			settings.LocalDev = true
1303		}
1304		if opts.AbsoluteGitHookPath {
1305			settings.AbsoluteGitHookPath = true
1306		}
1307	
1308		// Auto-enable external_agents setting if the agent is external.
1309		if external.IsExternal(ag) {
1310			settings.ExternalAgents = true
1311		}
1312	
1313		opts.applyStrategyOptions(settings)
1314	
1315		// Handle telemetry for non-interactive mode
1316		// Note: if telemetry is nil (not configured), it defaults to disabled
1317		if !opts.Telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
1318			f := false
1319			settings.Telemetry = &f
1320		}
1321	
1322		targetFile, configDisplay := settingsTargetFile(ctx, opts.UseLocalSettings, opts.UseProjectSettings)
1323		if err := saveSettingsToTarget(ctx, settings, targetFile); err != nil {
1324			return fmt.Errorf("failed to save settings: %w", err)
1325		}
1326	
1327		// Use settings values (merged from existing config + flags) for hook installation
1328		// This ensures re-running `entire enable --agent X` without flags preserves existing settings
1329		if _, err := strategy.InstallGitHook(ctx, true, settings.LocalDev, settings.AbsoluteGitHookPath); err != nil {
1330			return fmt.Errorf("failed to install git hooks: %w", err)
1331		}
1332		strategy.CheckAndWarnHookManagers(ctx, w, settings.LocalDev, settings.AbsoluteGitHookPath)
1333	
1334		if installedHooks == 0 {
1335			msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
1336			if ag.IsPreview() {
1337				msg += " (Preview)"
1338			}
1339			fmt.Fprintf(w, "%s\n", msg)
1340		} else {
1341			msg := fmt.Sprintf("Installed %d hooks for %s", installedHooks, ag.Description())
1342			if ag.IsPreview() {
1343				msg += " (Preview)"
1344			}
1345			fmt.Fprintf(w, "%s\n", msg)
1346		}
1347	
1348		fmt.Fprintf(w, "✓ Project configured (%s)\n", configDisplay)
1349	
1350		if _, err := maybePromptVercelDeploymentDisable(ctx, w, targetFile, nil); err != nil {
1351			return err
1352		}
1353	
1354		if err := strategy.EnsureSetup(ctx); err != nil {
1355			return fmt.Errorf("failed to setup strategy: %w", err)
1356		}
1357	
1358		fmt.Fprintln(w, "\nReady.")
1359	
1360		if repo, err := strategy.OpenRepository(ctx); err == nil && strategy.IsEmptyRepository(repo) {
1361			fmt.Fprintln(w)
1362			fmt.Fprintln(w, "Note: Session checkpoints require at least one commit. To get started,")
1363			fmt.Fprintln(w, "commit the configuration files (e.g. .entire/, .claude/).")
1364		}
1365	
1366		return nil
1367	}
