1562	// isCompletionConfigured checks if shell completion is already in the rc file.
1563	func isCompletionConfigured(rcFile string) bool {
1564		//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
1565		content, err := os.ReadFile(rcFile)
1566		if err != nil {
1567			return false // File doesn't exist or can't read, treat as not configured
1568		}
1569		return strings.Contains(string(content), "entire completion")
1570	}
1571	
1572	// appendShellCompletion adds the completion line to the rc file.
1573	func appendShellCompletion(rcFile, completionLine string) error {
1574		if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
1575			return fmt.Errorf("creating directory: %w", err)
1576		}
1577		//nolint:gosec // G302: Shell rc files need 0644 for user readability
1578		f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
1579		if err != nil {
1580			return fmt.Errorf("opening file: %w", err)
1581		}
1582		defer f.Close()
1583	
1584		_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
1585		if err != nil {
1586			return fmt.Errorf("writing completion: %w", err)
1587		}
1588		return nil
1589	}
