1634	func maybePromptVercelDeploymentDisable(ctx context.Context, w io.Writer, targetFile string, promptFn func() (bool, error)) (bool, error) {
1635		repoRoot, rootErr := paths.WorktreeRoot(ctx)
1636		if rootErr == nil {
1637			vercelJSONPath := filepath.Join(repoRoot, "vercel.json")
1638			hasVercelJSON := false
1639			if _, err := os.Stat(vercelJSONPath); err == nil {
1640				hasVercelJSON = true
1641			} else if !os.IsNotExist(err) {
1642				fmt.Fprintf(w, "Note: Skipping Vercel deployment update: could not check vercel.json: %v\n", err)
1643				return false, nil
1644			}
1645	
1646			hasVercelProject := hasVercelJSON
1647			if !hasVercelProject {
1648				for _, path := range []string{
1649					filepath.Join(repoRoot, ".vercel"),
1650					filepath.Join(repoRoot, "vercel.ts"),
1651				} {
1652					if _, err := os.Stat(path); err == nil {
1653						hasVercelProject = true
1654						break
1655					} else if !os.IsNotExist(err) {
1656						fmt.Fprintf(w, "Note: Skipping Vercel deployment update: could not check %s: %v\n", path, err)
1657						return false, nil
1658					}
1659				}
1660			}
1661	
1662			if !hasVercelProject {
1663				return false, nil
1664			}
1665	
1666			configDisplay := configDisplayProject
1667			if targetFile == settings.EntireSettingsLocalFile {
1668				configDisplay = configDisplayLocal
1669			}
1670	
1671			targetSettingsPath := filepath.Join(repoRoot, targetFile)
1672			targetSettings, err := settings.LoadFromFile(targetSettingsPath)
1673			if err != nil {
1674				return false, fmt.Errorf("load settings: %w", err)
1675			}
1676			if targetSettings.Vercel {
1677				return false, nil
1678			}
1679	
1680			if config, alreadyDisabled, loadErr := vercelconfig.Load(vercelJSONPath); loadErr == nil &&
1681				config != nil && alreadyDisabled {
1682				targetSettings.Vercel = true
1683				if err := saveSettingsToTarget(ctx, targetSettings, targetFile); err != nil {
1684					return false, fmt.Errorf("save settings: %w", err)
1685				}
1686				fmt.Fprintf(w, "✓ Updated %s to manage Vercel deployment blocking on `%s`\n", configDisplay, vercelconfig.BranchPattern)
1687				return true, nil
1688			}
1689	
1690			if promptFn == nil {
1691				if !interactive.CanPromptInteractively() {
1692					fmt.Fprintf(w, "Note: Vercel detected. Run `entire configure` interactively to disable deployments for `%s` branches.\n", vercelconfig.BranchPattern)
1693					return false, nil
1694				}
1695				promptFn = promptVercelDeploymentDisable
1696			}
1697	
1698			disableDeployments, err := promptFn()
1699			if err != nil {
1700				return false, fmt.Errorf("vercel prompt: %w", err)
1701			}
1702			if !disableDeployments {
1703				return false, nil
1704			}
1705	
1706			targetSettings.Vercel = true
1707			if err := saveSettingsToTarget(ctx, targetSettings, targetFile); err != nil {
1708				return false, fmt.Errorf("save settings: %w", err)
1709			}
1710	
1711			fmt.Fprintf(w, "✓ Updated %s to block Vercel deploys of Entire metadata branch\n", configDisplay)
1712			return true, nil
1713		}
1714	
1715		return false, nil
1716	}
