1738	// runUninstall completely removes Entire from the repository.
1739	func runUninstall(ctx context.Context, w, errW io.Writer, force bool) error {
1740		// Check if we're in a git repository
1741		if _, err := paths.WorktreeRoot(ctx); err != nil {
1742			fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
1743			return NewSilentError(errors.New("not a git repository"))
1744		}
1745	
1746		// Gather counts for display
1747		sessionStateCount := countSessionStates(ctx)
1748		shadowBranchCount := countShadowBranches(ctx)
1749		gitHooksInstalled := strategy.IsGitHookInstalled(ctx)
1750		agentsWithInstalledHooks := GetAgentsWithHooksInstalled(ctx)
1751		entireDirExists := checkEntireDirExists(ctx)
1752	
1753		// Check if there's anything to uninstall
1754		if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
1755			shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
1756			fmt.Fprintln(w, "Entire is not installed in this repository.")
1757			return nil
1758		}
1759	
1760		// Show confirmation prompt unless --force
1761		if !force {
1762			fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
1763			if entireDirExists {
1764				fmt.Fprintln(w, "  - .entire/ directory")
1765			}
1766			if gitHooksInstalled {
1767				fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
1768			}
1769			if sessionStateCount > 0 {
1770				fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
1771			}
1772			if shadowBranchCount > 0 {
1773				fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
1774			}
1775			if len(agentsWithInstalledHooks) > 0 {
1776				displayNames := make([]string, 0, len(agentsWithInstalledHooks))
1777				for _, name := range agentsWithInstalledHooks {
1778					if ag, err := agent.Get(name); err == nil {
1779						displayNames = append(displayNames, string(ag.Type()))
1780					}
1781				}
1782				fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
1783			}
1784			fmt.Fprintln(w)
1785	
1786			var confirmed bool
1787			form := NewAccessibleForm(
1788				huh.NewGroup(
1789					huh.NewConfirm().
1790						Title("Are you sure you want to uninstall Entire?").
1791						Affirmative("Yes, uninstall").
1792						Negative("Cancel").
1793						Value(&confirmed),
1794				),
1795			)
1796	
1797			if err := form.Run(); err != nil {
1798				return fmt.Errorf("confirmation cancelled: %w", err)
1799			}
1800	
1801			if !confirmed {
1802				fmt.Fprintln(w, "Uninstall cancelled.")
1803				return nil
1804			}
1805		}
1806	
1807		fmt.Fprintln(w, "\nUninstalling Entire CLI...")
1808	
1809		// 1. Remove agent hooks (lowest risk)
1810		if err := removeAgentHooks(ctx, w); err != nil {
1811			fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
1812		}
1813	
1814		// 2. Remove git hooks
1815		removed, err := strategy.RemoveGitHook(ctx)
1816		if err != nil {
1817			fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
1818		} else if removed > 0 {
1819			fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
1820		}
1821	
1822		// 3. Remove session state files
1823		statesRemoved, err := removeAllSessionStates(ctx)
1824		if err != nil {
1825			fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
1826		} else if statesRemoved > 0 {
1827			fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
1828		}
1829	
1830		// 4. Remove .entire/ directory
1831		if err := removeEntireDirectory(ctx); err != nil {
1832			fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
1833		} else if entireDirExists {
1834			fmt.Fprintln(w, "  Removed .entire directory")
1835		}
1836	
1837		// 5. Remove shadow branches
1838		branchesRemoved, err := removeAllShadowBranches(ctx)
1839		if err != nil {
1840			fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
1841		} else if branchesRemoved > 0 {
1842			fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
