1903	// removeAllSessionStates removes all session state files and the directory.
1904	func removeAllSessionStates(ctx context.Context) (int, error) {
1905		store, err := session.NewStateStore(ctx)
1906		if err != nil {
1907			return 0, fmt.Errorf("failed to create state store: %w", err)
1908		}
1909	
1910		// Count states before removing
1911		states, err := store.List(ctx)
1912		if err != nil {
1913			return 0, fmt.Errorf("failed to list session states: %w", err)
1914		}
1915		count := len(states)
1916	
1917		// Remove the entire directory
1918		if err := store.RemoveAll(); err != nil {
1919			return 0, fmt.Errorf("failed to remove session states: %w", err)
1920		}
1921	
1922		return count, nil
1923	}
1924	
1925	// removeEntireDirectory removes the .entire directory.
1926	func removeEntireDirectory(ctx context.Context) error {
1927		entireDirAbs, err := paths.AbsPath(ctx, paths.EntireDir)
1928		if err != nil {
1929			entireDirAbs = paths.EntireDir
1930		}
1931		if err := os.RemoveAll(entireDirAbs); err != nil {
1932			return fmt.Errorf("failed to remove .entire directory: %w", err)
1933		}
1934		return nil
1935	}
