func TestEnableCmd_YesFreshRepo_SelectsAllAgents(t *testing.T) {
	// Cannot use t.Parallel() because we use t.Chdir and t.Setenv
	setupTestRepo(t)
	testutil.WriteFile(t, ".", "f.txt", "init")
	testutil.GitAdd(t, ".", "f.txt")
	testutil.GitCommit(t, ".", "init")
	t.Setenv("ENTIRE_TEST_TTY", "0") // non-interactive — proves --yes bypasses prompts

	cmd := newEnableCmd()
	var stdout, stderr bytes.Buffer
	cmd.SetOut(&stdout)
	cmd.SetErr(&stderr)
	cmd.SetArgs([]string{"--yes"})

	if err := cmd.Execute(); err != nil {
		t.Fatalf("enable --yes error = %v\nstdout: %s\nstderr: %s", err, stdout.String(), stderr.String())
	}

	output := stdout.String()
	if !strings.Contains(output, "Ready.") {
		t.Errorf("expected 'Ready.' in output, got: %s", output)
	}
	// Should have selected multiple agents
	if !strings.Contains(output, "Selected agents:") {
		t.Errorf("expected 'Selected agents:' in output, got: %s", output)
	}

	// Verify settings were saved with telemetry enabled
	s, err := LoadEntireSettings(context.Background())
	if err != nil {
		t.Fatalf("failed to load settings: %v", err)
	}
	if !s.Enabled {
		t.Error("expected enabled=true")
	}
	if s.Telemetry == nil || *s.Telemetry != true {
		t.Errorf("expected telemetry=true (--yes default), got %v", s.Telemetry)
	}
}

