21	
22	// GitHubBootstrapOptions holds flags that let `entire enable` run on a folder
23	// that isn't yet a git repository. All fields are optional; supplying one
24	// skips the matching interactive prompt.
25	type GitHubBootstrapOptions struct {
26		// InitRepo is true if --init-repo was passed (accept git init without prompt).
27		InitRepo bool
28		// NoInitRepo is true if --no-init-repo was passed (decline without prompt).
29		NoInitRepo bool
30		// RepoName is the GitHub repository name (no owner).
31		RepoName string
32		// RepoOwner is the GitHub user or org login.
33		RepoOwner string
34		// RepoVisibility is one of "public", "private", "internal".
35		RepoVisibility string
36		// NoGitHub skips the GitHub repo creation step.
37		NoGitHub bool
38		// InitialCommitMessage overrides the default commit message prompt.
39		InitialCommitMessage string
40		// SkipInitialCommit leaves the newly-created files unstaged so the
41		// user can commit themselves. The GitHub repo (if requested) is
42		// still created, but nothing is pushed.
43		SkipInitialCommit bool
44	}
45	
46	// bootstrapRunner executes external commands. Tests override this to avoid
47	// shelling out to git/gh.
48	type bootstrapRunner interface {
49		// Run executes the command and returns stdout. Stderr is available on
50		// the returned *exec.ExitError for error reporting.
51		Run(ctx context.Context, name string, args ...string) (string, error)
52		// RunInDir is Run with an explicit working directory.
53		RunInDir(ctx context.Context, dir, name string, args ...string) (string, error)
54	}
55	
56	type execRunner struct{}
57	
58	func (execRunner) Run(ctx context.Context, name string, args ...string) (string, error) {
59		out, err := exec.CommandContext(ctx, name, args...).Output()
60		return string(out), err
61	}
62	
63	func (execRunner) RunInDir(ctx context.Context, dir, name string, args ...string) (string, error) {
64		cmd := exec.CommandContext(ctx, name, args...)
65		cmd.Dir = dir
66		out, err := cmd.Output()
67		return string(out), err
68	}
69	
70	// printBootstrapSection writes a small section header so the bootstrap
71	// output has visual grouping between phases (git init → agent setup →
72	// commit & push). Kept simple text so it renders correctly in accessible
73	// mode and non-TTY captures.
74	func printBootstrapSection(w io.Writer, title string) {
75		fmt.Fprintf(w, "\n━ %s\n", title)
76	}
77	
78	// errBootstrapDeclined signals that the user chose not to initialize a
79	// repo. Returned _before_ `git init` runs; callers fall back to the
80	// legacy "Not a git repository" error.
81	var errBootstrapDeclined = errors.New("bootstrap declined")
82	
83	// errBootstrapInterrupted signals that the user aborted a prompt _after_
84	// `git init` has already run. The local repo is in place but setup
85	// didn't complete; callers should surface that clearly instead of
86	// pretending no init happened.
87	var errBootstrapInterrupted = errors.New("bootstrap interrupted after init")
88	
89	// ghRepoNameRe validates GitHub repository names. GitHub allows
90	// alphanumerics, hyphens, underscores, and periods — including as the
91	// first character (e.g. `.github`). We don't enforce a leading-char
92	// restriction here; `validateRepoName` handles the specific names GitHub
93	// reserves (`.`, `..`). Any other edge case is left to GitHub to reject
94	// so we don't over-restrict.
95	var ghRepoNameRe = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
96	
97	// allowed visibility values.
98	const (
99		visibilityPublic   = "public"
100		visibilityPrivate  = "private"
101		visibilityInternal = "internal"
102	)
103	
104	// bootstrapState carries pre-setup decisions into the post-setup finalize
105	// step. The caller runs `runGitHubBootstrapInit` before agent setup to do
106	// `git init` + identity + gather GitHub choices, then runs
107	// `runGitHubBootstrapFinalize` afterwards so the initial commit captures
108	// the `.entire/`, `.claude/`, etc. files written during setup.
109	type bootstrapState struct {
110		runner     bootstrapRunner
111		cwd        string
112		useGitHub  bool
113		fullName   string // owner/name, if useGitHub
114		visibility string // public/private/internal, if useGitHub
115		commit     bool   // false means the user opted out of the initial commit
116		message    string // resolved initial commit message (empty when !commit)
117	}
118	
119	// runGitHubBootstrapInit handles the pre-setup half of "enable on a non-git
120	// folder": confirm + `git init`, ensure git identity, and (if we're going
121	// to create a GitHub repo) gather owner/name/visibility up front so all
122	// prompts happen before agent setup runs.
123	//
124	// Returns errBootstrapDeclined if the user declined the init prompt.
125	// Returns nil, nil if the caller is already inside a git repo and no
126	// bootstrap is needed (defensive; the caller typically gates on this).
127	func runGitHubBootstrapInit(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions) (*bootstrapState, error) {
128		return runGitHubBootstrapInitWith(ctx, w, errW, opts, execRunner{})
129	}
130	
131	// runGitHubBootstrapInitWith is the testable variant that accepts a runner.
132	func runGitHubBootstrapInitWith(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions, runner bootstrapRunner) (*bootstrapState, error) {
133		// paths.RepoRoot is unavailable here — we're bootstrapping _before_ a
134		// repo exists. Plain cwd is the correct target for `git init`.
135		cwd, err := os.Getwd() //nolint:forbidigo // no repo yet; git init runs in cwd
136		if err != nil {
137			return nil, fmt.Errorf("get working directory: %w", err)
138		}
139	
140		// Step 1: confirm we should git init here.
141		proceed, err := confirmInitRepo(w, cwd, opts)
142		if err != nil {
143			return nil, err
144		}
145		if !proceed {
146			return nil, errBootstrapDeclined
147		}
148	
149		// Step 2: git init.
150		printBootstrapSection(w, "Setting up git repository")
151		if err := gitInit(ctx, runner, cwd); err != nil {
152			return nil, fmt.Errorf("git init: %w", err)
153		}
154		// Clear cached worktree root so subsequent paths.WorktreeRoot calls pick
155		// up the freshly created repo.
156		paths.ClearWorktreeRootCache()
157		fmt.Fprintln(w, "✓ Initialized empty git repository")
158	
159		// Step 3: decide whether to create a GitHub repo. If gh is missing or the
160		// user passed --no-github, we skip that branch but still bootstrap the
161		// local repo.
162		useGitHub := !opts.NoGitHub
163		if useGitHub {
164			if !ghAvailable(ctx, runner) {
165				fmt.Fprintln(errW, "gh CLI not found. Install it from https://cli.github.com/ and run `gh auth login` to add a GitHub remote.")
166				fmt.Fprintln(errW, "Continuing with local initialization only.")
167				useGitHub = false
168			} else if !ghAuthenticated(ctx, runner) {
169				fmt.Fprintln(errW, "gh CLI is not authenticated. Run `gh auth login` to add a GitHub remote.")
170				fmt.Fprintln(errW, "Continuing with local initialization only.")
171				useGitHub = false
172			}
173		}
174	
175		// Step 3b: ask a simple yes/no before diving into owner/name/visibility
176		// prompts. Skip the confirm when any gh-specific flag is set (the flag
177		// implies intent) or when we're non-interactive (keep the documented
178		// happy path: default to yes).
179		if useGitHub && !ghFlagsProvided(opts) && interactive.CanPromptInteractively() {
180			confirmed, err := confirmCreateGitHubRepo()
181			if err != nil {
182				return nil, err
183			}
184			if !confirmed {
185				useGitHub = false
186			}
187		}
188	
189		// Step 4: collect GitHub repo details up front so all prompts are
190		// contiguous.
191		var fullName, visibility string
192		if useGitHub {
193			owner, name, vis, err := selectGitHubRepo(ctx, w, errW, runner, cwd, opts)
194			if err != nil {
195				return nil, err
196			}
197			fullName = owner + "/" + name
198			visibility = vis
199		}
200	
201		// Step 5: resolve commit message (+ skip decision) and ensure git
202		// identity. Must run after `git init` so `git config` reads are
203		// scoped correctly. If the user chose to skip the commit we still
204		// need an identity *if* we're going to create the GitHub repo,
205		// because gh may read local config; but we can skip the identity
206		// check when the user is fully opting out of both commit and
207		// remote to keep the flow minimal.
208		message, commit, err := resolveCommitMessage(opts)
209		if err != nil {
210			return nil, err
211		}
212		if commit {
213			if err := ensureGitIdentity(ctx, w, errW, runner, cwd); err != nil {
214				return nil, err
215			}
216		}
217	
218		return &bootstrapState{
219			runner:     runner,
220			cwd:        cwd,
221			useGitHub:  useGitHub,
222			fullName:   fullName,
223			visibility: visibility,
224			commit:     commit,
225			message:    message,
226		}, nil
227	}
228	
229	// runGitHubBootstrapWith runs the full bootstrap (init + finalize) in one
230	// call, used by tests that don't need to assert phasing. The real caller
231	// runs the two phases around agent setup.
232	func runGitHubBootstrapWith(ctx context.Context, w, errW io.Writer, opts GitHubBootstrapOptions, runner bootstrapRunner) error {
233		state, err := runGitHubBootstrapInitWith(ctx, w, errW, opts, runner)
234		if err != nil {
235			return err
236		}
237		return runGitHubBootstrapFinalize(ctx, w, state)
238	}
239	
240	// runGitHubBootstrapFinalize runs the post-setup half: stage + initial
241	// commit (now including any `.entire/`, agent hook, and settings files
242	// written by the enable flow), then create the GitHub repo and push.
243	// If the user opted out of the initial commit we still create the
244	// GitHub repo (if they opted in) but skip the push — there's nothing to
245	// push — and print next-step instructions.
246	func runGitHubBootstrapFinalize(ctx context.Context, w io.Writer, s *bootstrapState) error {
247		if s == nil {
248			return nil
249		}
250	
251		// Pick a single section title for this phase based on what we'll do.
252		if s.useGitHub || s.commit {
253			switch {
254			case s.useGitHub && s.commit:
255				printBootstrapSection(w, "Publishing to GitHub")
256			case s.useGitHub:
257				printBootstrapSection(w, "Creating GitHub repository")
258			default:
259				printBootstrapSection(w, "Finalizing")
260			}
261		}
262	
263		var committed bool
264		if s.commit {
265			c, err := doInitialCommit(ctx, s.runner, s.cwd, s.message)
266			if err != nil {
267				return fmt.Errorf("initial commit: %w", err)
268			}
269			committed = c
270			if committed {
271				fmt.Fprintf(w, "✓ Created initial commit (%s)\n", s.message)
272			} else {
273				fmt.Fprintln(w, "✓ Nothing to commit — the folder has no files yet")
274			}
275		}
276		if s.useGitHub {
277			if err := ghRepoCreate(ctx, s.runner, s.cwd, s.fullName, s.visibility, committed); err != nil {
278				return fmt.Errorf("gh repo create: %w", err)
279			}
280			fmt.Fprintf(w, "✓ Created %s (%s)\n", s.fullName, s.visibility)
281			fmt.Fprintf(w, "  https://github.com/%s\n", s.fullName)
282			if committed {
283				fmt.Fprintln(w, "✓ Pushed initial commit to origin")
284			}
285		}
286		if !s.commit {
287			fmt.Fprintln(w)
288			fmt.Fprintln(w, "Skipped initial commit. When you're ready:")
289			fmt.Fprintln(w, "  git add -A && git commit -m \"Initial commit\"")
290			if s.useGitHub {
291				fmt.Fprintln(w, "  git push -u origin HEAD")
292			}
293		}
294	
295		fmt.Fprintln(w, "\nDone.")
296		return nil
297	}
