361	// selectGitHubRepo gathers owner, repo name, and visibility, respecting
362	// supplied flags and falling back to interactive prompts.
363	func selectGitHubRepo(ctx context.Context, w, errW io.Writer, runner bootstrapRunner, cwd string, opts GitHubBootstrapOptions) (owner, name, visibility string, err error) {
364		currentUser, userErr := ghCurrentUser(ctx, runner)
365		if userErr != nil {
366			return "", "", "", fmt.Errorf("query current gh user: %w", userErr)
367		}
368		orgs, orgErr := ghListOrgs(ctx, runner)
369		if orgErr != nil {
370			// Missing read:org scope is non-fatal — we can still offer the user
371			// account. Warn and continue.
372			fmt.Fprintf(errW, "Warning: could not list organizations (%v). Only your user account is available.\n", orgErr)
373			orgs = nil
374		}
375	
376		owner, err = resolveOwner(w, currentUser, orgs, opts)
377		if err != nil {
378			return "", "", "", err
379		}
380	
381		name, err = resolveRepoName(ctx, w, errW, runner, owner, cwd, opts)
382		if err != nil {
383			return "", "", "", err
384		}
385	
386		visibility, err = resolveVisibility(owner, currentUser, opts)
387		if err != nil {
388			return "", "", "", err
389		}
390	
391		return owner, name, visibility, nil
392	}
