394	func resolveOwner(w io.Writer, currentUser string, orgs []string, opts GitHubBootstrapOptions) (string, error) {
395		owners := append([]string{currentUser}, orgs...)
396		if opts.RepoOwner != "" {
397			for _, candidate := range owners {
398				if candidate == opts.RepoOwner {
399					return opts.RepoOwner, nil
400				}
401			}
402			// Owner not in known list — allow it anyway; gh repo create will
403			// error out later if invalid. This supports orgs the token can't
404			// enumerate (e.g. missing read:org scope).
405			return opts.RepoOwner, nil
406		}
407		if len(owners) == 1 {
408			fmt.Fprintf(w, "Using GitHub owner: %s\n", currentUser)
409			return currentUser, nil
410		}
411		if !interactive.CanPromptInteractively() {
412			return currentUser, nil
413		}
414	
415		options := make([]huh.Option[string], 0, len(owners))
416		for _, o := range owners {
417			options = append(options, huh.NewOption(o, o))
418		}
419		selected := currentUser
420		form := NewAccessibleForm(
421			huh.NewGroup(
422				huh.NewSelect[string]().
423					Title("Choose the GitHub owner for the new repository").
424					Options(options...).
425					Value(&selected),
426			),
427		)
428		if err := form.Run(); err != nil {
429			if errors.Is(err, huh.ErrUserAborted) {
430				return "", errBootstrapInterrupted
431			}
432			return "", fmt.Errorf("owner prompt: %w", err)
433		}
434		return selected, nil
435	}
