437	func resolveRepoName(ctx context.Context, w, errW io.Writer, runner bootstrapRunner, owner, cwd string, opts GitHubBootstrapOptions) (string, error) {
438		suggested := slugifyRepoName(filepath.Base(cwd))
439	
440		if opts.RepoName != "" {
441			if err := validateRepoName(opts.RepoName); err != nil {
442				return "", err
443			}
444			exists, checkErr := ghRepoExists(ctx, runner, owner, opts.RepoName)
445			if checkErr != nil {
446				fmt.Fprintf(errW, "Warning: could not check if %s/%s already exists (%v).\n", owner, opts.RepoName, checkErr)
447			} else if exists {
448				return "", fmt.Errorf("repository %s/%s already exists on GitHub", owner, opts.RepoName)
449			}
450			return opts.RepoName, nil
451		}
452	
453		if !interactive.CanPromptInteractively() {
454			return suggested, nil
455		}
456	
457		name := suggested
458		for {
459			var input string
460			form := NewAccessibleForm(
461				huh.NewGroup(
462					huh.NewInput().
463						Title("Repository name").
464						Description(fmt.Sprintf("Press enter to use %q", name)).
465						Value(&input),
466				),
467			)
468			if err := form.Run(); err != nil {
469				if errors.Is(err, huh.ErrUserAborted) {
470					return "", errBootstrapInterrupted
471				}
472				return "", fmt.Errorf("repo name prompt: %w", err)
473			}
474			if strings.TrimSpace(input) != "" {
475				name = strings.TrimSpace(input)
476			}
477			if err := validateRepoName(name); err != nil {
478				fmt.Fprintf(errW, "Invalid name: %v\n", err)
479				continue
480			}
481			exists, checkErr := ghRepoExists(ctx, runner, owner, name)
482			if checkErr != nil {
483				fmt.Fprintf(errW, "Warning: could not check if %s/%s already exists (%v). Proceeding; gh will error out if it is taken.\n", owner, name, checkErr)
484				return name, nil
485			}
486			if exists {
487				fmt.Fprintf(w, "%s/%s already exists on GitHub. Pick a different name.\n", owner, name)
488				continue
489			}
490			return name, nil
491		}
492	}
