494	func resolveVisibility(owner, currentUser string, opts GitHubBootstrapOptions) (string, error) {
495		isOrg := owner != currentUser
496	
497		if opts.RepoVisibility != "" {
498			vis := strings.ToLower(opts.RepoVisibility)
499			switch vis {
500			case visibilityPublic, visibilityPrivate:
501				return vis, nil
502			case visibilityInternal:
503				if !isOrg {
504					return "", errors.New("visibility 'internal' is only available for organization repositories")
505				}
506				return vis, nil
507			default:
508				return "", fmt.Errorf("invalid visibility %q: must be one of public, private, internal", opts.RepoVisibility)
509			}
510		}
511		if !interactive.CanPromptInteractively() {
512			return visibilityPrivate, nil
513		}
514	
515		options := []huh.Option[string]{
516			huh.NewOption("Private", visibilityPrivate),
517			huh.NewOption("Public", visibilityPublic),
518		}
519		if isOrg {
520			options = append(options, huh.NewOption("Internal", visibilityInternal))
521		}
522		selected := visibilityPrivate
523		form := NewAccessibleForm(
524			huh.NewGroup(
525				huh.NewSelect[string]().
526					Title("Repository visibility").
527					Options(options...).
528					Value(&selected),
529			),
530		)
531		if err := form.Run(); err != nil {
532			if errors.Is(err, huh.ErrUserAborted) {
533				return "", errBootstrapInterrupted
534			}
535			return "", fmt.Errorf("visibility prompt: %w", err)
536		}
537		return selected, nil
538	}
