540	// resolveCommitMessage returns the message to use for the initial
541	// commit. The second return value is false when the user chose to skip
542	// the initial commit entirely; callers must skip `doInitialCommit` and
543	// any subsequent push.
544	func resolveCommitMessage(opts GitHubBootstrapOptions) (string, bool, error) {
545		const defaultMsg = "Initial commit"
546	
547		if opts.SkipInitialCommit {
548			return "", false, nil
549		}
550		if opts.InitialCommitMessage != "" {
551			return opts.InitialCommitMessage, true, nil
552		}
553		if !interactive.CanPromptInteractively() {
554			return defaultMsg, true, nil
555		}
556	
557		const (
558			choiceDefault   = "default"
559			choiceCustomize = "custom"
560			choiceSkip      = "skip"
561		)
562		choice := choiceDefault
563		form := NewAccessibleForm(
564			huh.NewGroup(
565				huh.NewSelect[string]().
566					Title("Initial commit").
567					Options(
568						huh.NewOption(`Commit with default message "Initial commit"`, choiceDefault),
569						huh.NewOption("Customize message...", choiceCustomize),
570						huh.NewOption("Skip — I'll commit manually later", choiceSkip),
571					).
572					Value(&choice),
573			),
574		)
575		if err := form.Run(); err != nil {
576			if errors.Is(err, huh.ErrUserAborted) {
577				return "", false, errBootstrapInterrupted
578			}
579			return "", false, fmt.Errorf("commit message prompt: %w", err)
580		}
581	
582		switch choice {
583		case choiceSkip:
584			return "", false, nil
585		case choiceCustomize:
586			input := defaultMsg
587			custom := NewAccessibleForm(
588				huh.NewGroup(
589					huh.NewInput().
590						Title("Initial commit message").
591						Value(&input),
592				),
593			)
594			if err := custom.Run(); err != nil {
595				if errors.Is(err, huh.ErrUserAborted) {
596					return "", false, errBootstrapInterrupted
597				}
598				return "", false, fmt.Errorf("commit message prompt: %w", err)
599			}
600			if strings.TrimSpace(input) == "" {
601				return defaultMsg, true, nil
602			}
603			return input, true, nil
604		default:
605			return defaultMsg, true, nil
606		}
607	}
