617	// doInitialCommit stages all files and creates a commit. Returns whether a
618	// commit was actually created (false if there were no files to stage).
619	func doInitialCommit(ctx context.Context, runner bootstrapRunner, dir, message string) (bool, error) {
620		if _, err := runner.RunInDir(ctx, dir, "git", "add", "-A"); err != nil {
621			return false, fmt.Errorf("git add: %w", err)
622		}
623		// Check if the staging area has anything at all.
624		out, err := runner.RunInDir(ctx, dir, "git", "status", "--porcelain")
625		if err != nil {
626			return false, fmt.Errorf("git status: %w", err)
627		}
628		if strings.TrimSpace(out) == "" {
629			return false, nil
630		}
631		// Disable GPG signing for this commit only. Fresh environments often
632		// have commit.gpgsign=true inherited from a global config but no
633		// working signer; passing -c keeps the user's global config intact.
634		if _, err := runner.RunInDir(ctx, dir, "git", "-c", "commit.gpgsign=false", "commit", "-m", message); err != nil {
635			return false, fmt.Errorf("git commit: %w", err)
636		}
637		return true, nil
638	}
