640	// ensureGitIdentity guarantees the repo has a user.name/user.email set at
641	// some scope. If neither is configured, we source values from `gh api user`
642	// when available, otherwise prompt (interactive) or fail with a helpful
643	// message (non-interactive). Values are written to the local repo config
644	// only, so the user's global state is never mutated.
645	func ensureGitIdentity(ctx context.Context, w, _ io.Writer, runner bootstrapRunner, dir string) error {
646		// `git config --get` exits non-zero when the key isn't set. Treat any
647		// error as "unset" rather than fatal so we can fall through to sourcing
648		// the identity from elsewhere.
649		nameOut, nameErr := runner.RunInDir(ctx, dir, "git", "config", "--get", "user.name")
650		emailOut, emailErr := runner.RunInDir(ctx, dir, "git", "config", "--get", "user.email")
651		var existingName, existingEmail string
652		if nameErr == nil {
653			existingName = strings.TrimSpace(nameOut)
654		}
655		if emailErr == nil {
656			existingEmail = strings.TrimSpace(emailOut)
657		}
658		if existingName != "" && existingEmail != "" {
659			return nil
660		}
661	
662		// Only try to fill in what's missing. If the user has a name set
663		// globally but no email, we want to keep their name and just source
664		// the email.
665		var ghName, ghEmail string
666		if ghAvailable(ctx, runner) && ghAuthenticated(ctx, runner) {
667			if n, e, err := ghUserIdentity(ctx, runner); err == nil {
668				ghName, ghEmail = n, e
669			}
670		}
671	
672		name, email, err := resolveGitIdentity(w, existingName, existingEmail, ghName, ghEmail)
673		if err != nil {
674			return err
675		}
676	
677		// Write only the fields that were missing. Leaving the already-set
678		// field alone means we never silently replace the user's globally
679		// configured name/email.
680		if existingName == "" {
681			if _, err := runner.RunInDir(ctx, dir, "git", "config", "user.name", name); err != nil {
682				return fmt.Errorf("git config user.name: %w", err)
683			}
684		}
685		if existingEmail == "" {
686			if _, err := runner.RunInDir(ctx, dir, "git", "config", "user.email", email); err != nil {
687				return fmt.Errorf("git config user.email: %w", err)
688			}
689		}
690		return nil
691	}
692	
693	// resolveGitIdentity returns the name/email to use, given any values
694	// already configured at a wider scope and any values from `gh api user`.
695	// Only prompts for fields that are still empty after those fallbacks.
696	func resolveGitIdentity(w io.Writer, existingName, existingEmail, ghName, ghEmail string) (string, string, error) {
697		name := existingName
698		email := existingEmail
699		if name == "" {
700			name = ghName
701		}
702		if email == "" {
703			email = ghEmail
704		}
705	
706		if name != "" && email != "" {
707			// Announce only when we had to fill something in from gh —
708			// silence is fine when the user's existing config covered both.
709			if (existingName == "" && ghName != "") || (existingEmail == "" && ghEmail != "") {
710				fmt.Fprintf(w, "Using git identity: %s <%s>\n", name, email)
711			}
712			return name, email, nil
713		}
714	
715		if !interactive.CanPromptInteractively() {
716			return "", "", errors.New(`git identity not configured. Set it with:
717	  git config --global user.name "Your Name"
718	  git config --global user.email "you@example.com"`)
719		}
720	
721		// Prompt only for the still-missing fields.
722		var fields []huh.Field
723		if name == "" {
724			fields = append(fields, huh.NewInput().Title("Git user.name").Value(&name))
725		}
726		if email == "" {
727			fields = append(fields, huh.NewInput().Title("Git user.email").Value(&email))
728		}
729		form := NewAccessibleForm(huh.NewGroup(fields...))
730		if err := form.Run(); err != nil {
731			if errors.Is(err, huh.ErrUserAborted) {
732				return "", "", errBootstrapInterrupted
733			}
734			return "", "", fmt.Errorf("git identity prompt: %w", err)
735		}
736		if strings.TrimSpace(name) == "" || strings.TrimSpace(email) == "" {
737			return "", "", errors.New("git user.name and user.email are both required")
738		}
739		return strings.TrimSpace(name), strings.TrimSpace(email), nil
740	}
