742	// ghUserResponse is the subset of `gh api user` fields we care about.
743	type ghUserResponse struct {
744		ID    int64  `json:"id"`
745		Login string `json:"login"`
746		Name  string `json:"name"`
747		Email string `json:"email"`
748	}
749	
750	// ghUserIdentity returns a best-effort (name, email) from `gh api user`.
751	// Missing name falls back to login; missing email falls back to the GitHub
752	// no-reply address, which is always accepted by GitHub.
753	func ghUserIdentity(ctx context.Context, runner bootstrapRunner) (string, string, error) {
754		out, err := runner.Run(ctx, "gh", "api", "user")
755		if err != nil {
756			return "", "", fmt.Errorf("gh api user: %w", err)
757		}
758		var resp ghUserResponse
759		if err := json.Unmarshal([]byte(out), &resp); err != nil {
760			return "", "", fmt.Errorf("parse gh user response: %w", err)
761		}
762		name := resp.Name
763		if name == "" {
764			name = resp.Login
765		}
766		email := resp.Email
767		if email == "" && resp.ID != 0 && resp.Login != "" {
768			email = fmt.Sprintf("%d+%s@users.noreply.github.com", resp.ID, resp.Login)
769		}
770		if name == "" || email == "" {
771			return "", "", errors.New("gh user response missing identity fields")
772		}
773		return name, email, nil
774	}
