815	// ghRepoExists checks whether <owner>/<name> exists on GitHub.
816	func ghRepoExists(ctx context.Context, runner bootstrapRunner, owner, name string) (bool, error) {
817		_, err := runner.Run(ctx, "gh", "repo", "view", owner+"/"+name, "--json", "name")
818		if err == nil {
819			return true, nil
820		}
821		var exitErr *exec.ExitError
822		if errors.As(err, &exitErr) {
823			msg := string(exitErr.Stderr)
824			if strings.Contains(msg, "Could not resolve") || strings.Contains(msg, "not found") || strings.Contains(msg, "Not Found") {
825				return false, nil
826			}
827		}
828		return false, fmt.Errorf("gh repo view: %w", err)
829	}
