831	// ghRepoCreate creates a GitHub repo from the local source directory, adds
832	// origin as its remote, and pushes if there's anything to push.
833	func ghRepoCreate(ctx context.Context, runner bootstrapRunner, dir, fullName, visibility string, hasCommits bool) error {
834		// Create the remote repo and add origin, but don't push yet. We push
835		// separately below with --no-verify so the pre-push hook doesn't run
836		// on this first push: the entire/checkpoints/v1 branch has nothing to
837		// checkpoint (no sessions yet), and if it's pushed alongside the
838		// default branch GitHub can pick it as the default.
839		//
840		// Capture `gh repo create`'s stdout instead of streaming it — its own
841		// "✓ Created repository..." / "✓ Added remote..." lines would
842		// duplicate our own summary in runGitHubBootstrapFinalize.
843		args := []string{
844			"repo", "create", fullName,
845			"--" + visibility,
846			"--source=.",
847			"--remote=origin",
848		}
849		if _, err := runner.RunInDir(ctx, dir, "gh", args...); err != nil {
850			return fmt.Errorf("gh repo create: %w", ghRunnerErr(err))
851		}
852		if hasCommits {
853			// -q silences "Enumerating objects..." etc. --no-verify bypasses
854			// the pre-push hook so entire/checkpoints/v1 isn't pushed
855			// alongside the default branch.
856			if _, err := runner.RunInDir(ctx, dir, "git", "push", "-q", "--no-verify", "-u", "origin", "HEAD"); err != nil {
857				return fmt.Errorf("git push: %w", ghRunnerErr(err))
858			}
859		}
860		return nil
861	}
862	
863	// ghRunnerErr extracts an exec.ExitError's stderr into the returned
864	// error so the user sees a useful diagnostic when gh/git fail under a
865	// captured-stdout call.
866	func ghRunnerErr(err error) error {
867		var exitErr *exec.ExitError
868		if errors.As(err, &exitErr) && len(exitErr.Stderr) > 0 {
869			return fmt.Errorf("%w: %s", err, strings.TrimSpace(string(exitErr.Stderr)))
870		}
871		return err
872	}
873	
874	// slugifyRepoName turns a folder name into a GitHub-safe repo name. Invalid
875	// characters are replaced with '-', and runs of '-' are collapsed.
876	func slugifyRepoName(folder string) string {
877		var b strings.Builder
878		b.Grow(len(folder))
879		for _, r := range folder {
880			switch {
881			case (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9'):
882				b.WriteRune(r)
883			case r == '-' || r == '_' || r == '.':
884				b.WriteRune(r)
885			default:
886				b.WriteRune('-')
887			}
888		}
889		slug := b.String()
